type Settings = {
  notificationsEnabled: boolean
}

const globalStore = globalThis as unknown as { __settings?: Settings }

if (!globalStore.__settings) {
  globalStore.__settings = { notificationsEnabled: false }
}

export function getSettings(): Settings {
  return globalStore.__settings!
}

export function toggleNotifications(): Settings {
  globalStore.__settings!.notificationsEnabled =
    !globalStore.__settings!.notificationsEnabled
  return globalStore.__settings!
}

import { getSettings } from '@/lib/settings-store'
import { toggleNotificationPreference } from './actions'
import { NotificationToggle } from './notification-toggle'

export default function Home() {
  const { notificationsEnabled } = getSettings()

  return (
    <main>
      <h1>Settings</h1>
      <NotificationToggle
        enabled={notificationsEnabled}
        toggle={toggleNotificationPreference}
      />
    </main>
  )
}

'use client'

export function NotificationToggle({
  enabled,
  toggle,
}: {
  enabled: boolean
  toggle: () => Promise<void>
}) {
  return (
    <form action={toggle}>
      <p>
        Email notifications: <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <button type="submit">
        {enabled ? 'Turn notifications off' : 'Turn notifications on'}
      </button>
    </form>
  )
}

import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
